class Solution:
    def placeWordInCrossword(self, board: List[List[str]], word: str) -> bool:
        m, n = len(board), len(board[0])
        L = len(word)

        def blocked(x, y):
            return x < 0 or y < 0 or x >= m or y >= n or board[x][y] == '#'

        def fits(i, j, dx, dy):
            if not blocked(i - dx, j - dy):
                return False
            for k in range(L):
                x, y = i + dx * k, j + dy * k
                if blocked(x, y):
                    return False
                if board[x][y] != ' ' and board[x][y] != word[k]:
                    return False
            return blocked(i + dx * L, j + dy * L)

        dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        for i in range(m):
            for j in range(n):
                for dx, dy in dirs:
                    if fits(i, j, dx, dy):
                        return True
        return False

