class Solution {
public:
    bool placeWordInCrossword(vector<vector<char>>& board, string word) {
        int m = board.size(), n = board[0].size(), L = word.size();
        int dirs[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};
        auto blocked = [&](int x, int y) {
            return x < 0 || y < 0 || x >= m || y >= n || board[x][y] == '#';
        };
        auto fits = [&](int i, int j, int dx, int dy) {
            if (!blocked(i - dx, j - dy)) return false;
            for (int k = 0; k < L; k++) {
                int x = i + dx * k, y = j + dy * k;
                if (blocked(x, y)) return false;
                if (board[x][y] != ' ' && board[x][y] != word[k]) return false;
            }
            return blocked(i + dx * L, j + dy * L);
        };
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                for (auto& d : dirs)
                    if (fits(i, j, d[0], d[1])) return true;
        return false;
    }
};

