class Solution {
    public boolean placeWordInCrossword(char[][] board, String word) {
        int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};
        for (int i = 0; i < board.length; i++)
            for (int j = 0; j < board[0].length; j++)
                for (int[] d : dirs)
                    if (fits(board, i, j, d[0], d[1], word)) return true;
        return false;
    }
    private boolean fits(char[][] b, int i, int j, int dx, int dy, String w) {
        if (!blocked(b, i - dx, j - dy)) return false;
        for (int k = 0; k < w.length(); k++) {
            int x = i + dx * k, y = j + dy * k;
            if (blocked(b, x, y)) return false;
            if (b[x][y] != ' ' && b[x][y] != w.charAt(k)) return false;
        }
        return blocked(b, i + dx * w.length(), j + dy * w.length());
    }
    private boolean blocked(char[][] b, int x, int y) {
        return x < 0 || y < 0 || x >= b.length || y >= b[0].length || b[x][y] == '#';
    }
}

