class Solution:
    def placeWordInCrossword(self, board: List[List[str]], word: str) -> bool:
        def ok(run, w):
            return all(c == ' ' or c == ch for c, ch in zip(run, w))

        rev = word[::-1]
        L = len(word)
        segs = []
        for row in board:
            segs.extend(''.join(row).split('#'))
        for col in zip(*board):
            segs.extend(''.join(col).split('#'))
        return any(len(s) == L and (ok(s, word) or ok(s, rev)) for s in segs)

