class Solution {
public:
    bool placeWordInCrossword(vector<vector<char>>& board, string word) {
        int m = board.size(), n = board[0].size(), L = word.size();
        string rev(word.rbegin(), word.rend());
        auto ok = [&](const string& s) {
            if ((int)s.size() != L) return false;
            auto match = [&](const string& w) {
                for (int i = 0; i < L; i++)
                    if (s[i] != ' ' && s[i] != w[i]) return false;
                return true;
            };
            return match(word) || match(rev);
        };
        vector<string> lines;
        for (int i = 0; i < m; i++) lines.emplace_back(board[i].begin(), board[i].end());
        for (int j = 0; j < n; j++) {
            string col;
            for (int i = 0; i < m; i++) col += board[i][j];
            lines.push_back(col);
        }
        for (auto& line : lines) {
            string cur;
            for (char c : line) {
                if (c == '#') { if (ok(cur)) return true; cur.clear(); }
                else cur += c;
            }
            if (ok(cur)) return true;
        }
        return false;
    }
};

