class Solution {
    public boolean placeWordInCrossword(char[][] board, String word) {
        int m = board.length, n = board[0].length;
        String rev = new StringBuilder(word).reverse().toString();
        StringBuilder[] lines = new StringBuilder[m + n];
        for (int i = 0; i < m + n; i++) lines[i] = new StringBuilder();
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                lines[i].append(board[i][j]);
                lines[m + j].append(board[i][j]);
            }
        for (StringBuilder line : lines)
            for (String seg : line.toString().split("#"))
                if (fits(seg, word) || fits(seg, rev)) return true;
        return false;
    }
    private boolean fits(String seg, String w) {
        if (seg.length() != w.length()) return false;
        for (int i = 0; i < w.length(); i++)
            if (seg.charAt(i) != ' ' && seg.charAt(i) != w.charAt(i)) return false;
        return true;
    }
}

