var placeWordInCrossword = function(board, word) {
    const m = board.length, n = board[0].length;
    const rev = [...word].reverse().join("");
    const fits = seg => seg.length === word.length &&
        [word, rev].some(w => [...seg].every((c, k) => c === " " || c === w[k]));
    const lines = [];
    for (let i = 0; i < m; i++) lines.push(board[i].join(""));
    for (let j = 0; j < n; j++) lines.push(board.map(row => row[j]).join(""));
    return lines.some(line => line.split("#").some(fits));
};
